function __bcFitLegendPhotos63(){
 for(
  let svg
  of document.querySelectorAll(
   `svg.bc-legendary-photo`
  )
 ){
  if(svg.closest(`.item-tile`))
   continue;

  let card=
   svg.closest(
    `.metro-equipment,article,button,[class*="equipment"],[class*="debrief"],[class*="settle"]`
   );

  if(!card)continue;

  let cs=getComputedStyle(card);

  if(cs.position===`static`)
   card.style.position=`relative`;

  card.style.overflow=`hidden`;

  Object.assign(
   svg.style,
   {
    position:`absolute`,
    left:`auto`,
    right:`4%`,
    top:`9%`,
    width:`43%`,
    height:`70%`,
    maxWidth:`43%`,
    maxHeight:`70%`,
    margin:`0`,
    transform:`none`,
    overflow:`visible`
   }
  );

  let img=
   svg.querySelector(`image`);

  if(img){
   img.setAttribute(
    `preserveAspectRatio`,
    `xMidYMid meet`
   );
  }
 }
}

