/* BC LEGENDARY DROP CONFIRM 64 */
function __bcLegendDropModal64(item,onConfirm){
 let old=
  document.querySelector(
   `#bc-legend-drop-confirm-64`
  );

 if(old)old.remove();

 let overlay=
  document.createElement(`div`);

 overlay.id=
  `bc-legend-drop-confirm-64`;

 Object.assign(
  overlay.style,
  {
   position:`fixed`,
   inset:`0`,
   zIndex:`99999`,
   display:`grid`,
   placeItems:`center`,
   background:`rgba(4,13,18,.72)`,
   backdropFilter:`blur(4px)`
  }
 );

 let box=
  document.createElement(`div`);

 Object.assign(
  box.style,
  {
   width:`min(460px,calc(100vw - 36px))`,
   border:`1px solid #e7c45a88`,
   background:`linear-gradient(180deg,#17282e,#0e1d22)`,
   boxShadow:`0 20px 70px #000b`,
   padding:`24px`
  }
 );

 box.innerHTML=
  `<div style="font-size:11px;letter-spacing:.16em;color:#e8c75e;margin-bottom:10px">LEGENDARY ITEM WARNING</div>
   <div style="font-size:20px;font-weight:800;color:#f5f4ec;margin-bottom:9px">전설 무기를 바닥에 버릴까요?</div>
   <div style="font-size:14px;line-height:1.6;color:#b9c8cc">
    <b style="color:#fff">${item?.name??`전설 무기`}</b><br>
    이 행동은 실제 전리품 상자를 생성합니다. 다른 플레이어가 획득할 수 있습니다.
   </div>
   <div style="display:flex;gap:10px;margin-top:22px">
    <button data-bc-cancel style="flex:1;padding:12px;border:1px solid #52666c;background:#15272d;color:#d7e0e2;font-weight:700;cursor:pointer">취소</button>
    <button data-bc-confirm style="flex:1;padding:12px;border:1px solid #edc64f;background:#d2a72f;color:#111;font-weight:900;cursor:pointer">버리기</button>
   </div>`;

 overlay.appendChild(box);
 document.body.appendChild(overlay);

 const close=()=>overlay.remove();

 box.querySelector(`[data-bc-cancel]`).onclick=close;

 overlay.onclick=e=>{
  if(e.target===overlay)close();
 };

 box.querySelector(`[data-bc-confirm]`).onclick=()=>{
  close();
  onConfirm();
 };
}

(()=>{
 if(WebSocket.prototype.__bcLegendDrop64)return;

 const original=
  WebSocket.prototype.send;

 WebSocket.prototype.__bcLegendDrop64=
  original;

 WebSocket.prototype.send=function(data){
  try{
   if(typeof data===`string`){
    const message=
     JSON.parse(data);

    if(
     message &&
     typeof message.type===`string` &&
     message.type.includes(`drop`) &&
     message.legendaryConfirm!==true
    ){
     let itemId=
      message.itemId;

     if(!itemId&&message.slot){
      const player=
       typeof cv===`function`
        ?cv()
        :null;

      itemId=
       player?.equipment?.[message.slot]??
       player?.gear?.[message.slot];
     }

     const item=
      itemId
       ?Z(itemId)
       :null;

     if(item?.legendaryBlade===true){
      const socket=this;

      __bcLegendDropModal64(
       item,
       ()=>{
        original.call(
         socket,
         JSON.stringify({
          ...message,
          legendaryConfirm:true
         })
        );
       }
      );

      return;
     }
    }
   }
  }catch{}

  return original.call(this,data);
 };
})();

