/* BC LEGENDARY SCOPE 67 */
var __bcLegendScope67=false;

function __bcLegendHeld67(){
 const p=
  typeof cv===`function`
   ?cv()
   :null;

 if(
  !p ||
  !p.alive ||
  p.downed ||
  p.searching
 )return null;

 const slot=
  p.activeWeaponSlot;

 const id=
  p.equipment?.[slot]??
  p.weaponId;

 const weapon=
  id
   ?Z(id)
   :null;

 return weapon?.legendaryBlade===true
  ?weapon
  :null;
}

function __bcLegendScopeOff67(){
 if(!__bcLegendScope67)return;

 __bcLegendScope67=false;

 try{
  Q.resetScope();
 }catch{}
}

window.addEventListener(
 `mousedown`,
 e=>{
  if(e.button!==2)return;

  const weapon=
   __bcLegendHeld67();

  if(!weapon)return;

  e.preventDefault();

  __bcLegendScope67=true;

  /*
   The stock scope handler rejects melee and calls resetScope().
   Apply our 6x scope immediately AFTER that handler finishes.
  */
  setTimeout(
   ()=>{
    if(
     __bcLegendScope67 &&
     __bcLegendHeld67()
    ){
     try{
      Q.setScope(
       `scope-6x`,
       true,
       1
      );
     }catch{}
    }
   },
   0
  );
 },
 true
);

window.addEventListener(
 `mouseup`,
 e=>{
  if(e.button===2)
   __bcLegendScopeOff67();
 },
 true
);

window.addEventListener(
 `blur`,
 __bcLegendScopeOff67,
 true
);

window.addEventListener(
 `contextmenu`,
 e=>{
  if(__bcLegendHeld67()){
   e.preventDefault();
  }
 },
 true
);

