/* BC LEGENDARY CARD CENTER 78 */
function __bcLegendCardCenter74(){
 for(const svg of document.querySelectorAll(`svg.bc-legendary-photo`)){
  /* BC 80: equipped weapon artwork follows the exact ordinary gun stage. */
  const equippedWeaponStage=svg.closest(`.inv-gun-image`);

  if(equippedWeaponStage){
   /* Do NOT override .inv-gun-image position/inset. Stock CSS owns it. */
   const props={
    position:`relative`,
    left:`auto`,
    right:`auto`,
    top:`auto`,
    bottom:`auto`,
    width:`100%`,
    height:`100%`,
    minWidth:`0`,
    minHeight:`0`,
    maxWidth:`100%`,
    maxHeight:`100%`,
    margin:`0`,
    transform:`none`,
    overflow:`visible`,
    pointerEvents:`none`,
    zIndex:`auto`
   };

   for(const [key,value] of Object.entries(props)){
    svg.style.setProperty(
     key.replace(/[A-Z]/g,c=>`-${c.toLowerCase()}`),
     value,
     `important`
    );
   }

   const image=svg.querySelector(`image`);
   if(image){
    image.setAttribute(`x`,`0`);
    image.setAttribute(`y`,`0`);
    image.setAttribute(`width`,`200`);
    image.setAttribute(`height`,`120`);
    image.setAttribute(`preserveAspectRatio`,`xMidYMid meet`);
   }

   continue;
  }

  if(
   svg.closest(`.container-items`) ||
   svg.closest(`.metro-equipment`) ||
   svg.closest(`.item-inspect`)
  )continue;

  /*
   Both menu storage (.item-grid) and live raid inventory (.inv-item-grid)
   must keep the artwork in normal flex flow, exactly like ordinary items.
  */
  const menuGrid=svg.closest(`.item-grid`);
  const raidGrid=svg.closest(`.inv-item-grid`);

  if(menuGrid||raidGrid){
   const card=svg.closest(raidGrid?`.inv-item-tile`:`.item-tile`);
   if(!card)continue;

   card.style.setProperty(`position`,`relative`,`important`);
   card.style.setProperty(`overflow`,`hidden`,`important`);

   const height=raidGrid?`69px`:`90px`;
   const margin=raidGrid?`0`:`3px auto 7px`;

   const props={
    position:`relative`,
    left:`auto`,
    right:`auto`,
    top:`auto`,
    bottom:`auto`,
    width:`100%`,
    height,
    minHeight:height,
    maxWidth:`100%`,
    maxHeight:height,
    margin,
    transform:`none`,
    overflow:`visible`,
    pointerEvents:`none`,
    flex:`0 0 ${height}`
   };

   for(const [key,value] of Object.entries(props)){
    svg.style.setProperty(
     key.replace(/[A-Z]/g,c=>`-${c.toLowerCase()}`),
     value,
     `important`
    );
   }

   const image=svg.querySelector(`image`);
   if(image){
    image.setAttribute(`x`,`0`);
    image.setAttribute(`y`,`0`);
    image.setAttribute(`width`,`200`);
    image.setAttribute(`height`,`120`);
    image.setAttribute(`preserveAspectRatio`,`xMidYMid meet`);
   }

   continue;
  }

  const card=svg.closest(`button,article`);
  if(!card)continue;

  const rect=card.getBoundingClientRect();
  if(rect.width<90||rect.width>360||rect.height<90||rect.height>380)continue;

  card.style.setProperty(`position`,`relative`,`important`);
  card.style.setProperty(`overflow`,`hidden`,`important`);

  const props={
   position:`absolute`,
   left:`50%`,
   right:`auto`,
   top:`16px`,
   width:`76%`,
   height:`56%`,
   maxWidth:`76%`,
   maxHeight:`56%`,
   margin:`0`,
   transform:`translateX(-50%)`,
   overflow:`visible`,
   pointerEvents:`none`
  };

  for(const [key,value] of Object.entries(props)){
   svg.style.setProperty(
    key.replace(/[A-Z]/g,c=>`-${c.toLowerCase()}`),
    value,
    `important`
   );
  }

  const image=svg.querySelector(`image`);
  if(image){
   image.setAttribute(`x`,`0`);
   image.setAttribute(`y`,`0`);
   image.setAttribute(`width`,`200`);
   image.setAttribute(`height`,`120`);
   image.setAttribute(`preserveAspectRatio`,`xMidYMid meet`);
  }
 }
}

