/* ===== BLUECAP 29 SPECTATOR / CORPSE / GOLD INSTANCE PATCH ===== */

var bcSpectating=false;
var bcSpectatorId=null;
var bcSpectatorOutcome=`dead`;
var bcSpectatorLossReport=null;
var bcSpectatorFinishing=false;
var bcIgnoreRaid=false;

function bcSpectatorCandidates(){
 return (e_?.players??[]).filter(
  e=>e.id!==t_&&e.alive&&!e.boarded
 );
}

function bcSpectatorOverlay(){
 if(!bcSpectating||!e_)return;

 let e=bcSpectatorCandidates();
 let t=e.find(e=>e.id===bcSpectatorId);

 let n=document.querySelector(`#bc-spectator`);

 if(!n){
  n=document.createElement(`div`);
  n.id=`bc-spectator`;

  n.style.cssText=
   `position:fixed;left:50%;bottom:34px;transform:translateX(-50%);`+
   `z-index:99999;background:rgba(8,14,17,.9);border:1px solid #697773;`+
   `box-shadow:0 12px 36px #0008;padding:12px 14px;display:flex;`+
   `align-items:center;gap:10px;color:#f1eee5;font:600 14px sans-serif;`+
   `backdrop-filter:blur(9px)`;

  document.body.append(n);
 }

 n.innerHTML=
  `<button id="bc-spec-prev" style="padding:8px 12px">‹</button>`+
  `<div style="min-width:190px;text-align:center">`+
   `<small style="display:block;color:#9ca6a3">관전 중</small>`+
   `<b style="font-size:16px">${X(t?.username??`팀원`)}</b>`+
   `<span style="display:block;color:#aab2af;margin-top:3px">${e.length}명 생존</span>`+
  `</div>`+
  `<button id="bc-spec-next" style="padding:8px 12px">›</button>`+
  `<button id="bc-spec-home" style="padding:8px 14px;margin-left:6px">로비로 나가기</button>`;

 n.querySelector(`#bc-spec-prev`).onclick=
  ()=>bcSpectatorSelect(-1);

 n.querySelector(`#bc-spec-next`).onclick=
  ()=>bcSpectatorSelect(1);

 n.querySelector(`#bc-spec-home`).onclick=
  ()=>bcLeaveSpectator();
}

function bcSpectatorSelect(e=0){
 if(!bcSpectating||!e_)return;

 let n=bcSpectatorCandidates();

 if(!n.length){
  if(!bcSpectatorFinishing){
   bcSpectatorFinishing=true;
   bcSpectating=false;
   bcSpectatorId=null;

   Q.playerId=t_;

   document.querySelector(`#bc-spectator`)?.remove();

   Mv(
    bcSpectatorOutcome,
    bcSpectatorLossReport
   );
  }

  return;
 }

 let r=n.findIndex(e=>e.id===bcSpectatorId);

 if(r<0)r=0;
 else if(e)r=(r+e+n.length)%n.length;

 let i=n[r];

 bcSpectatorId=i.id;

 Q.playerId=i.id;
 Q.pred.set(i.x,0,i.z);

 if(Number.isFinite(i.yaw)){
  Q.aim.set(
   Math.sin(i.yaw),
   0,
   Math.cos(i.yaw)
  );
 }

 bcSpectatorOverlay();
}

function bcEnterSpectator(e,t){
 bcSpectatorOutcome=e;
 bcSpectatorLossReport=t;
 bcSpectatorFinishing=false;
 bcSpectating=true;
 bcIgnoreRaid=false;

 I_?.reset?.();

 k_=false;
 O_?.clear?.();

 Q.moveX=0;
 Q.moveZ=0;
 Q.sprinting=false;
 Q.resetScope();

 bcSpectatorSelect(0);

 R_(
  `완전 사망했습니다. 살아있는 팀원을 관전합니다.`,
  true
 );
}

function bcLeaveSpectator(){
 bcSpectating=false;
 bcSpectatorId=null;
 bcSpectatorFinishing=false;

 bcIgnoreRaid=true;

 C_=false;
 l_=false;
 e_=null;
 n_=`home`;

 document.querySelector(`#bc-spectator`)?.remove();

 Q.playerId=t_;
 Q.hideout();
 __bcSyncLobbyParty127();
 __bcRefreshLobbyParty127();

 let e=document.querySelector(`#raid-loading`);
 if(e)e.hidden=true;

 rv();

 void mt(`/me`)
  .then(e=>{
   B_(e.profile);
   rv();
  })
  .catch(()=>{});
}

